async function overlayTap(factory,label){let last;for(let i=0;i<10;i++){try{const btn=factory().first();await btn.waitFor({state:'visible',timeout:2500});await btn.scrollIntoViewIfNeeded();await page.waitForTimeout(260);const fresh=factory().first();const info=await fresh.evaluate(b=>{const c=b.closest('#members .memberCard');return{id:c?.dataset?.memberId22||c?.dataset?.memberId46||c?.dataset?.memberId||'',text:(b.textContent||'').trim()}});const r=await fresh.boundingBox();if(!r)throw new Error('no box');const x=r.x+r.width/2,y=r.y+r.height/2;await fresh.evaluate((b,{x,y,w,h,label})=>{document.querySelectorAll('.qaTouchOverlay27').forEach(n=>n.remove());const c=b.closest('#members .memberCard');const o=document.createElement('span');o.className='qaTouchOverlay27';o.textContent='';o.dataset.qa=label;o.style.cssText=`position:fixed;left:${x-w/2}px;top:${y-h/2}px;width:${w}px;height:${h}px;z-index:2147483000;display:block;background:transparent;pointer-events:auto;touch-action:manipulation`;c.appendChild(o)},{x,y,w:r.width,h:r.height,label});const hit=await page.evaluate(({x,y})=>document.elementsFromPoint(x,y).slice(0,8).map(el=>({tag:el.tagName,cls:el.className,text:(el.textContent||'').trim().slice(0,30)})),{x,y});console.log('HIT '+label,JSON.stringify(hit));if(!String(hit[0]?.cls||'').includes('qaTouchOverlay27'))throw new Error('overlay not top target '+JSON.stringify(hit));await page.touchscreen.tap(x,y);await page.waitForTimeout(180);console.log('EVENTS '+label,JSON.stringify(await page.evaluate(()=>window.__qaTouchEvents.splice(0))));console.log('TRACE '+label,await page.evaluate(()=>window.__kokmatchV27Last||''));await page.evaluate(()=>document.querySelectorAll('.qaTouchOverlay27').forEach(n=>n.remove()));return info}catch(e){last=e;await page.waitForTimeout(160)}}throw new Error('overlay tap failed '+label+': '+String(last?.message||last))}
async function realTap(factory,label){const el=factory().first();await el.waitFor({state:'visible'});await el.scrollIntoViewIfNeeded();await page.waitForTimeout(220);const fresh=factory().first();const r=await fresh.boundingBox();if(!r)throw new Error('no box '+label);const x=r.x+r.width/2,y=r.y+r.height/2;const hit=await page.evaluate(({x,y})=>document.elementsFromPoint(x,y).slice(0,6).map(el=>({tag:el.tagName,id:el.id,cls:el.className,text:(el.textContent||'').trim().slice(0,30)})),{x,y});console.log('HIT '+label,JSON.stringify(hit));await page.touchscreen.tap(x,y);await page.waitForTimeout(180);console.log('EVENTS '+label,JSON.stringify(await page.evaluate(()=>window.__qaTouchEvents.splice(0))));console.log('TRACE28 '+label,await page.evaluate(()=>window.__kokmatchV28Last||''));}
