await page.waitForTimeout(500);
const enterInfo=await overlayTap(()=>page.locator('#members .memberCard[data-member-id22="m1"] .btn.enter'),'overlay attendance');await page.waitForTimeout(450);if(!actionBodies.some(x=>x.action==='set_member_attendance'&&x.memberId===enterInfo.id&&x.mode==='waiting'))throw new Error('overlay attendance missing '+JSON.stringify({enterInfo,actionBodies}));console.log('PASS overlay attendance');
